import math
from shapely.geometry import Polygon, Point
from shapely.ops import unary_union
from shapely.affinity import rotate, translate

def inv(a): return math.tan(a)-a
def make(z, mod=1.5, pa_deg=20, back=0.4):
    rp=mod*z/2; rb=rp*math.cos(math.radians(pa_deg)); rt=rp+mod; rr=rp-1.25*mod
    pa=math.radians(pa_deg)
    def ha(r):
        ar=math.acos(min(1.0, rb/r))
        return math.pi/(2*z)-back/(2*rp)+inv(pa)-inv(ar)
    rs=max(rb,rr); steps=4; pitch=2*math.pi/z
    def pol(r,a): return (r*math.cos(a), r*math.sin(a))
    tooth=[pol(rr,-pitch/2), pol(rr,-ha(rs))]
    for i in range(1,steps+1):
        r=rs+(rt-rs)*i/steps; tooth.append(pol(r,-ha(r)))
    for i in range(steps-1,-1,-1):
        r=rs+(rt-rs)*i/steps; tooth.append(pol(r,ha(r)))
    tooth+= [pol(rr,ha(rs))]
    polys=[]
    for i in range(z):
        a=pitch*i; ca,sa=math.cos(a),math.sin(a)
        polys.append(Polygon([(x*ca-y*sa, x*sa+y*ca) for x,y in tooth]))
    return unary_union([Point(0,0).buffer(rr, resolution=96)]+polys)

def place(p,a,c): return translate(rotate(p,a,origin=(0,0)), xoff=c[0], yoff=c[1])
centres=[(21,30),(43.9,30),(65.3,30),(85.2,30)]
zs=[18,12,16,10]; P={z:make(z) for z in zs}
phases={12:180-180/12, 16:0.0, 10:180-180/10}
for n in range(3):
    zA,zB=zs[n],zs[n+1]; phB=phases[zB]; sign = -1 if n%2==0 else 1
    # cumulative: gear angles relative: aB = phB + (angleB0) ; gearA angle a (gear1 a, others driven)
    # compute via ratios from gear1: th = [a, -1.5a, 1.125a, -1.8a] plus phases
    dmin=9; at=None
    for k in range(361):
        a1=k*1.0
        th=[a1, phases[12]-1.5*a1, 1.125*a1, phases[10]-1.8*a1]
        A=place(P[zA],th[n],centres[n]); B=place(P[zB],th[n+1],centres[n+1])
        d=A.distance(B)
        if d<dmin: dmin,at=d,a1
    print(f"mesh{n+1} z{zA}-z{zB}: min tooth gap over full turn = {dmin:.3f} mm at gear1={at}")
